CREATE TABLE `owner_notification_settings` (`id` VARCHAR(40) NOT NULL, `revision` INTEGER NOT NULL DEFAULT 1, `payloadEncrypted` LONGTEXT NOT NULL, `createdAt` DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3), `updatedAt` DATETIME(3) NOT NULL, PRIMARY KEY (`id`)) DEFAULT CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci;
CREATE TABLE `owner_notification_seen` (`eventId` BIGINT UNSIGNED NOT NULL, PRIMARY KEY (`eventId`)) DEFAULT CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci;
ALTER TABLE `owner_notification_seen` ADD CONSTRAINT `owner_notification_seen_eventId_fkey` FOREIGN KEY (`eventId`) REFERENCES `payment_events`(`id`) ON DELETE CASCADE ON UPDATE CASCADE;
CREATE TABLE `owner_notification_deliveries` (`id` VARCHAR(191) NOT NULL, `dedupeKey` VARCHAR(160) NOT NULL, `channel` VARCHAR(16) NOT NULL, `title` VARCHAR(160) NOT NULL, `message` TEXT NOT NULL, `status` VARCHAR(16) NOT NULL DEFAULT 'PENDING', `attempts` INTEGER NOT NULL DEFAULT 0, `nextAttemptAt` DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3), `leaseOwner` VARCHAR(40) NULL, `lockedUntil` DATETIME(3) NULL, `lastError` VARCHAR(80) NULL, `createdAt` DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3), `updatedAt` DATETIME(3) NOT NULL, UNIQUE INDEX `owner_notification_deliveries_dedupeKey_key` (`dedupeKey`), INDEX `owner_notification_deliveries_status_nextAttemptAt_idx` (`status`, `nextAttemptAt`), PRIMARY KEY (`id`)) DEFAULT CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci;
